import { defineConfig } from "vite-plus";
import type { OxlintOverride } from "vite-plus/lint";

const ignorePatterns = [
  // Generated by @tanstack/router-plugin. Committed so type checks work before a build.
  "**/routeTree.gen.ts",
  // Agent skills installed from upstream (tracked by skills-lock.json). Must stay byte-identical.
  ".agents/**",
  // Symlinks to .agents/skills. The rest of .kiro/ (hooks, settings, steering) is checked like any other file.
  ".kiro/skills/**",
];

const runtimeImportMessage =
  "Runtime-specific code belongs in an entry file such as apps/api/src/server.ts (docs/adr/0007).";

const runtimeImports = {
  paths: [
    { name: "bun", message: runtimeImportMessage },
    { name: "@hono/node-server", message: runtimeImportMessage },
    { name: "@hono/aws-lambda", message: runtimeImportMessage },
    { name: "@hono/node-ws", message: runtimeImportMessage },
  ],
  patterns: [{ group: ["bun:*"], message: runtimeImportMessage }],
};

// Runtime-specific globals (docs/adr/0007). no-restricted-globals stops the bare name, and no-restricted-properties
// stops the same name read from globalThis.
const runtimeGlobals = [
  { name: "process", message: "Read environment variables from `c.env`." },
  { name: "Bun", message: runtimeImportMessage },
  { name: "Buffer", message: "Use Uint8Array, TextEncoder or TextDecoder." },
];
const runtimeGlobalRules: Record<string, ["error", ...Record<string, string>[]]> = {
  "no-restricted-globals": [
    "error",
    ...runtimeGlobals,
    // global.process is the Node.js alias of globalThis.process, and no-restricted-properties cannot name it.
    { name: "global", message: "Use `globalThis`, and not for the globals of Node.js or Bun." },
    { name: "__dirname", message: "Use `import.meta.url`." },
    { name: "__filename", message: "Use `import.meta.url`." },
    { name: "require", message: "Use `import`." },
  ],
  "no-restricted-properties": [
    "error",
    ...runtimeGlobals.map(({ name, message }) => ({
      object: "globalThis",
      property: name,
      message: `${message} (\`globalThis.${name}\` is the same global.)`,
    })),
  ],
};

// Module boundaries (docs/adr/0026). The sample feature is a modular monolith: each module is a package under
// packages/, and apps/api only assembles them. A module may import the modules listed for it here, and they
// point one way: closing (締め) → approval (承認) → claim (申請). shared imports no module.
// repo-policy checks that every project under packages/ other than shared is a key here and has the fixtures.
const scope = "@agent-software-factory";
const modules: Record<string, readonly string[]> = {
  claim: [],
  approval: ["claim"],
  closing: ["approval", "claim"],
};
// The layers of a module (src/<layer>/), with the layers each may import. domain imports nothing but the types of
// shared (below).
const layers: Record<string, readonly string[]> = {
  domain: [],
  application: ["domain"],
  infrastructure: ["application", "domain"],
  http: ["application", "domain"],
};

const moduleNames = Object.keys(modules);
const packageNames = ["shared", ...moduleNames];
const moduleMessage = (from: string, to: string) =>
  `${from} must not import ${to}: modules depend one way, closing → approval → claim, and shared imports none. ` +
  `Move the code that needs ${to} into a module that may import it, or move what both need into shared ` +
  "(docs/adr/0026).";
const deepMessage =
  `Import another package by its name only (${scope}/<name>). Its package.json exports its src/index.ts and ` +
  "nothing else; export what you need from there (docs/adr/0026).";
const layerMessage =
  "Layers point inward: domain imports nothing, application imports domain, and infrastructure and http import " +
  "application and domain but not each other (docs/adr/0026).";
const domainMessage =
  `domain imports nothing but types of ${scope}/shared (\`import type\`). Put the code that needs a library or ` +
  "another module in application or infrastructure (docs/adr/0026).";

// Imports that reach past the index.ts of another package: a subpath of the package name, or a relative path
// into <package>/src. The package.json exports stop the first from resolving, and this rule names both.
const deepImports = [
  { regex: `^${scope}/[^/]+/`, message: deepMessage },
  { regex: `^\\.{1,2}/(?:.*/)?(?:${packageNames.join("|")})/src(?:/|$)`, message: deepMessage },
];
const forbiddenModules = (from: string, allowed: readonly string[]) =>
  moduleNames
    .filter((name) => name !== from && !allowed.includes(name))
    .map((name) => ({ name: `${scope}/${name}`, message: moduleMessage(from, name) }));

// The options of no-restricted-imports for a file of module `name`, in `layer` (undefined: src/index.ts and
// other files outside the layers). Oxlint keeps only the last override that sets a rule for a file, so each
// override carries all the restrictions of its files.
function moduleImports(name: string, layer?: string) {
  const patterns: Record<string, unknown>[] = [...runtimeImports.patterns, ...deepImports];
  if (layer !== undefined) {
    const other = Object.keys(layers).filter((l) => l !== layer && !layers[layer]?.includes(l));
    if (other.length > 0)
      patterns.push({
        regex: `^(?:\\./)?(?:\\.\\./)+(?:${other.join("|")})(?:/|$)`,
        message: layerMessage,
      });
  }
  if (layer === "domain")
    // Oxlint 1.89 checks the patterns in order, and a negated group that matches ends the check of that import.
    // So the value imports of shared are stopped first, then every package but shared.
    patterns.push(
      { regex: `^${scope}/shared$`, allowTypeImports: true, message: domainMessage },
      { regex: "^[^.@]", message: domainMessage },
      { group: ["@*/*", `!${scope}/shared`], message: domainMessage },
    );
  return {
    paths: [...runtimeImports.paths, ...forbiddenModules(name, modules[name] ?? [])],
    patterns,
  };
}

const moduleOverrides = moduleNames.flatMap((name): OxlintOverride[] => [
  {
    files: [`packages/${name}/src/**`],
    rules: { "no-restricted-imports": ["error", moduleImports(name)] },
  },
  ...Object.keys(layers).map((layer): OxlintOverride => ({
    files: [`packages/${name}/src/${layer}/**`],
    rules: { "no-restricted-imports": ["error", moduleImports(name, layer)] },
  })),
]);

const childProcessMessage =
  "Start git and other processes through gitIn() or runIn() from tools/scripts/src/test/sandbox.ts, which refuse " +
  'to act outside the sandbox (docs/tooling/ci.md ("スクリプトのテスト")).';

// Rules of typescript-eslint's `recommended-type-checked` that Oxlint does not enable by default, plus three
// stricter ones (docs/adr/0020). They stop `any`, `!`, narrowing `as` and @ts-ignore, the ways to silence a
// type error. A description is required after @ts-expect-error.
const typedRules: Record<string, "error" | ["error", ...unknown[]]> = {
  "typescript/ban-ts-comment": ["error", { "ts-expect-error": "allow-with-description" }],
  "typescript/no-explicit-any": "error",
  "typescript/no-empty-object-type": "error",
  "typescript/no-namespace": "error",
  "typescript/no-require-imports": "error",
  "typescript/no-unnecessary-type-constraint": "error",
  "typescript/no-unsafe-function-type": "error",
  "typescript/no-misused-promises": "error",
  "typescript/no-unnecessary-type-assertion": "error",
  "typescript/no-unsafe-argument": "error",
  "typescript/no-unsafe-assignment": "error",
  "typescript/no-unsafe-call": "error",
  "typescript/no-unsafe-member-access": "error",
  "typescript/no-unsafe-return": "error",
  "typescript/no-unsafe-enum-comparison": "error",
  "typescript/only-throw-error": "error",
  "typescript/prefer-promise-reject-errors": "error",
  "typescript/require-await": "error",
  "typescript/restrict-plus-operands": "error",
  // Stricter than recommended-type-checked.
  "typescript/switch-exhaustiveness-check": "error",
  "typescript/no-non-null-assertion": "error",
  "typescript/no-unsafe-type-assertion": "error",
};

// Root config for `vp check` / `vp lint` / `vp fmt`.
// Task orchestration and caching are handled by Nx, not `vp run` (see docs/adr/0002).
export default defineConfig({
  fmt: {
    ignorePatterns,
  },
  lint: {
    ignorePatterns,
    jsPlugins: [{ name: "vite-plus", specifier: "vite-plus/oxlint-plugin" }],
    rules: {
      "vite-plus/prefer-vite-plus-imports": "error",
      ...typedRules,
    },
    options: {
      typeAware: true,
      typeCheck: true,
      // A warning fails `vp check` too. Without this a warning-level rule such as no-floating-promises
      // passes CI (docs/adr/0020).
      denyWarnings: true,
      reportUnusedDisableDirectives: "error",
    },
    overrides: [
      // Agent-written tests: block .only (runs a subset) and .skip (hides a failing test), and a test that
      // passes without checking anything: no expect, an expect that runs only on one branch, or an expect
      // that asserts nothing (#30). The last three are in Oxlint's correctness category, which listing the plugin
      // already turns on as warnings; they are named here so that they stay errors whatever the defaults.
      // tools/scripts/src/test/fixtures/expect.test.ts fails `vp check` if one is turned off.
      // See docs/code-review/agent-pull-requests.md.
      {
        files: ["**/*.test.ts", "**/*.test.tsx"],
        plugins: ["vitest"],
        rules: {
          "vitest/no-focused-tests": "error",
          "vitest/no-disabled-tests": "error",
          "vitest/expect-expect": "error",
          "vitest/no-conditional-expect": "error",
          "vitest/valid-expect": "error",
        },
      },
      // ADR 0007: apps/api/src uses Web standard APIs only, so the app runs on Node.js,
      // Lambda and Cloudflare Workers. Runtime-specific code lives in the entry files below.
      {
        files: ["apps/api/src/**", "packages/*/src/**"],
        plugins: ["import"],
        rules: {
          "import/no-nodejs-modules": "error",
          // apps/api imports the modules by their package names only (docs/adr/0026).
          "no-restricted-imports": [
            "error",
            {
              paths: runtimeImports.paths,
              patterns: [...runtimeImports.patterns, ...deepImports],
            },
          ],
          ...runtimeGlobalRules,
        },
      },
      // Runtime-specific entry files and tests. Add new entry files (Lambda, Workers, ...) here.
      // They still import the modules by their package names only (docs/adr/0026).
      {
        files: ["apps/api/src/server.ts", "apps/api/src/**/*.test.ts"],
        // A plugin rule can only be turned off in an override that also lists the plugin.
        plugins: ["import"],
        rules: {
          "import/no-nodejs-modules": "off",
          "no-restricted-imports": ["error", { patterns: deepImports }],
          "no-restricted-globals": "off",
          "no-restricted-properties": "off",
        },
      },
      // Tests of the packages. They leave the runtime restrictions of the override above, but not the import
      // restrictions of the modules, which are set in the overrides below (docs/adr/0026).
      {
        files: ["packages/*/src/**/*.test.ts"],
        plugins: ["import"],
        rules: {
          "import/no-nodejs-modules": "off",
          "no-restricted-globals": "off",
          "no-restricted-properties": "off",
        },
      },
      // Module boundaries (docs/adr/0026): the direction between the modules, imports by the package name only,
      // and the direction between the layers of a module.
      {
        files: ["packages/shared/src/**"],
        rules: {
          "no-restricted-imports": [
            "error",
            {
              paths: [...runtimeImports.paths, ...forbiddenModules("shared", [])],
              patterns: [...runtimeImports.patterns, ...deepImports],
            },
          ],
        },
      },
      ...moduleOverrides,
      // Tests of tools/scripts run from Git hooks, where a git command can act on this repository instead of
      // the temporary one (docs/tooling/ci.md ("スクリプトのテスト")). They start processes only through the
      // helpers in tools/scripts/src/test/, which are not test files. Dynamic import() and createRequire are
      // outside this rule; tools/scripts/src/test/isolation.test.ts catches what they would do.
      {
        files: ["tools/scripts/src/**/*.test.ts"],
        rules: {
          "no-restricted-imports": [
            "error",
            {
              paths: [
                { name: "node:child_process", message: childProcessMessage },
                { name: "child_process", message: childProcessMessage },
              ],
            },
          ],
        },
      },
      // The title of every test in apps/*/src is written in Japanese, so that the verbose test report reads as a
      // list of what the code guarantees. The rule is in apps/api/lint/test-title-plugin.ts. Tests of the tools
      // and of the lint plugins themselves are outside this rule.
      {
        files: ["apps/*/src/**/*.test.ts", "apps/*/src/**/*.test.tsx"],
        jsPlugins: [{ name: "test-title", specifier: "./apps/api/lint/test-title-plugin.ts" }],
        rules: { "test-title/japanese-title": "error" },
      },
      // React rules (hooks, keys, state in effects) and JSX accessibility (alt text, anchors, keyboard
      // handlers). Oxlint's default rules are each plugin's correctness category (docs/web-frontend/static-analysis.md).
      // On top of them: a key that is the index of an array, and the effects React says you might not need
      // (eslint-plugin-react-you-might-not-need-an-effect, in the catalog of pnpm-workspace.yaml). Its
      // no-derived-state reports what react/set-state-in-effect reports, and says what to compute during render
      // instead, so the built-in rule is off. apps/web/src/__fixtures__/react.tsx fails `vp check` if one is
      // turned off.
      {
        files: ["apps/web/src/**"],
        plugins: ["react", "jsx-a11y"],
        jsPlugins: [
          {
            name: "react-effect",
            specifier: "eslint-plugin-react-you-might-not-need-an-effect",
          },
        ],
        rules: {
          "react/no-array-index-key": "error",
          "react/set-state-in-effect": "off",
          "react-effect/no-derived-state": "error",
          "react-effect/no-chain-state-updates": "error",
          "react-effect/no-event-handler": "error",
          "react-effect/no-adjust-state-on-prop-change": "error",
          "react-effect/no-reset-all-state-on-prop-change": "error",
          "react-effect/no-pass-live-state-to-parent": "error",
          "react-effect/no-pass-data-to-parent": "error",
          "react-effect/no-external-store-subscription": "error",
          "react-effect/no-initialize-state": "error",
        },
      },
      // The frontend logs nothing to the browser console (docs/logging/frontend.md).
      // Collect client errors with an error tracking service instead.
      {
        files: ["apps/web/src/**"],
        rules: { "no-console": "error" },
      },
      // Code that opens an XSS hole (docs/web-frontend/static-analysis.md). The rules are in
      // apps/web/lint/xss-plugin.ts, because Oxlint's built-in ones cannot say what to write instead.
      // Turning one off takes a disable comment with a reason, and a blanket disable is not allowed.
      {
        files: ["apps/web/src/**"],
        jsPlugins: [{ name: "web-xss", specifier: "./apps/web/lint/xss-plugin.ts" }],
        plugins: ["unicorn"],
        rules: {
          "web-xss/no-html-injection": "error",
          "web-xss/no-javascript-url": "error",
          "web-xss/no-dynamic-code": "error",
          "web-xss/require-disable-reason": "error",
          "unicorn/no-abusive-eslint-disable": "error",
          // web-xss/no-dynamic-code reports eval with a message that says what to write instead.
          "no-eval": "off",
        },
      },
    ],
  },
});
